1	// baselining worker — the DETERMINISTIC self-refresh, as agent_preprocessing
2	// (agent-preprocessing DESIGN §7, E4). This is `agent_model: 'sonnet'` with
3	// `agent_preprocessing: 'node worker.mjs'`, so the scheduler runs THIS FILE as a
4	// subprocess (cwd = this task dir) bounded by `agent_preprocessing_timeout`,
5	// BEFORE any agent. It absorbs everything about the nightly refresh that is
6	// dependency-free code — so most nights are AGENTLESS and quiet, and an agent is
7	// requested only when real judgment is left (owner decision, 2026-07-23):
8	//
9	//   agent requested  ⇔  a pending AGENTIC migration note exists
10	//                    OR  the converge changed things AND check_the_world is not green.
11	//   no change, or changed-but-green with no agentic note  →  agentless night.
12	//
13	// What it does, Action-side, over the one sanctioned non-MCP surface (the Action
14	// GITHUB_TOKEN in env) and a direct PUBLIC canon fetch (owner §10: canon is
15	// public — no token, no tarball channel):
16	//   1. shallow-clone canon at its head sha (then drop .git → a rootless tree, so
17	//      apply-vendor-set skips the ancestry guards that a shallow clone can't
18	//      satisfy — it is head by construction);
19	//   2. run the CLONED canon's vendoring/apply-vendor-set.mjs to converge
20	//      .claudinite/shared/ and stamp it (compute+apply, one snapshot);
21	//   3. run the cloned converge-wiring.mjs (scheduler workflow + hashed cron + the
22	//      tasks' declared required_secrets, settings hooks, retired-import removal),
23	//      and ask the owner for any declared secret the repo hasn't configured;
24	//   4. apply the MECHANICAL migration notes (aliases/materialize/rewrite) via the
25	//      cloned migrations/apply.mjs — idempotent;
26	//   5. detect pending AGENTIC notes (registry.mjs `agenticMigrations`, gated on
27	//      the prior stamp day, same-day inclusive #330) and, if any, HOLD the stamp
28	//      at the day before the earliest one so the agent still sees the note (the
29	//      stamp/agentic coupling rule);
30	//   6. deliver the converge as ONE commit on the per-cycle maintenance branch via
31	//      NATIVE git (find the family's open PR by head-branch prefix and reuse it,
32	//      else mint a dated branch and open the PR), arming auto-merge per the
33	//      member's `maintenance.delivery` and DISPATCHING the repo's PR CI on the
34	//      branch — the GITHUB_TOKEN push emits no pull_request run of its own
35	//      (#565), so the checks the arm waits on must be started explicitly;
36	//   7. request the agent (write CLAUDINITE_REQUEST_AGENT) only when judgment is
37	//      left — the scheduler files `ready-for-agent` iff this file appears (§3,
38	//      conditional handoff). NO code→agent data channel: the file is a pure
39	//      control signal; the agent discovers its work by reading the repo (the
40	//      pushed branch, the held stamp, the pending note).
41	//
42	// Self-contained — imports only node builtins statically (the pack-independence
43	// barrier forbids reaching into the engine). The vendoring/migrations machinery
44	// is canon-internal (vendoring/ is never vendored, #385), so the worker INVOKES
45	// the freshly-fetched canon's scripts as subprocesses and DYNAMIC-imports its
46	// registry from the temp clone path — never a static import of engine code.
47	//
48	// This SUPERSEDES the per-cycle maintenance-branch naming of PR #407 (that PR
49	// reworked the OLD fleet-apply MCP path; baselining's delivery is native git
50	// Action-side and carries its own prefix/find-by-prefix here).
51	
52	import { execFileSync } from 'node:child_process';
53	import { readFileSync, writeFileSync, existsSync, rmSync, mkdtempSync } from 'node:fs';
54	import { join } from 'node:path';
55	import { tmpdir } from 'node:os';
56	import { pathToFileURL } from 'node:url';
57	
58	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
59	const MAINT_PREFIX = 'claudinite/maintenance';
60	const API = 'https://api.github.com';
61	
62	// --- pure helpers (exported, unit-tested git-free) --------------------------
63	
64	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
65	// `pr` → review are the permanent legacy aliases (same tolerance as fleet-apply);
66	// anything else is invalid (null) and fails the run rather than guessing.
67	export function normalizeDelivery(raw) {
68	  const v = String(raw ?? '').trim();
69	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
70	  if (v === 'review' || v === 'pr') return 'review';
71	  return null;
72	}
73	
74	// The default a repo gets when it never declared one.
75	export const DEFAULT_DELIVERY = 'auto-merge';
76	
77	// `maintenance.delivery` is always EXPLICIT — but a key that is simply absent is
78	// DRIFT, not an error, and drift is what a converge exists to repair. A repo
79	// adopted before the key existed, or one whose key was hand-removed, would
80	// otherwise fail baselining every night forever with nothing that could ever fix
81	// it (the only writer is check_the_world --init, which runs once at adoption).
82	// So: materialize the default into .claudinite-checks.json and carry on — it
83	// rides the same maintenance commit as the rest of the converge, and the repo
84	// self-heals on one cycle.
85	//
86	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
87	// the worker cannot honour, and silently substituting a default would deliver
88	// the opposite of what they asked for. That still fails the run (delivery: null).
89	//
90	// Returns { delivery, materialize } — `delivery` null only for the unrecognized
91	// case. A content-free value (empty/whitespace) carries no intent, so it is
92	// treated as absent rather than as a typo.
93	export function resolveDelivery(raw) {
94	  if (raw == null || String(raw).trim() === '') {
95	    return { delivery: DEFAULT_DELIVERY, materialize: true };
96	  }
97	  return { delivery: normalizeDelivery(raw), materialize: false };
98	}
99	
100	// The pending AGENTIC notes: those dated on/after the DAY of the prior stamp
101	// (same-day inclusive, #330), oldest first. `agenticList` is registry.mjs
102	// `agenticMigrations(all)` — already filtered to records carrying a valid
103	// `agentic` note (a malformed note throws THERE, aborting the run loudly).
104	export function pendingAgentic(agenticList, priorUpdated) {
105	  const priorDay = String(priorUpdated ?? '').slice(0, 10);
106	  return [...(agenticList ?? [])]
107	    .filter((m) => !priorDay || String(m.landed) >= priorDay)
108	    .sort((a, b) => String(a.landed).localeCompare(String(b.landed)));
109	}
110	
111	// HOLD the stamp at the day before the earliest pending agentic note (the
112	// stamp/agentic coupling rule): the note stays selected next run until the agent
113	// lands it and advances the stamp itself. Returns the held ISO datetime, or null
114	// when nothing is pending (the stamp advances normally).
115	export function heldStamp(pending) {
116	  if (!pending?.length) return null;
117	  const d = new Date(`${String(pending[0].landed).slice(0, 10)}T00:00:00.000Z`);
118	  d.setUTCDate(d.getUTCDate() - 1);
119	  return d.toISOString();
120	}
121	
122	// A per-cycle maintenance branch name — dated + a short seed so each cycle gets a
123	// distinct branch (superseding #407's scheme, native-git side). `seed` is passed
124	// in so this is pure; main() generates it.
125	export function maintenanceBranchName(dateStr, seed) {
126	  return `${MAINT_PREFIX}-${dateStr}-${seed}`;
127	}
128	
129	// The family's open maintenance PR, found by head-branch PREFIX (idempotency is
130	// by prefix now that the name carries a per-cycle seed): a run reuses that PR so
131	// they never pile up night-over-night. null → mint a fresh one. The whole PR is
132	// returned, not just its ref, because the reuse path needs its `node_id` to
133	// re-assert the auto-merge arm each cycle.
134	export function openMaintenancePull(pulls, prefix = MAINT_PREFIX) {
135	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
136	}
137	
138	// Its head branch alone — the shape most callers want.
139	export function openMaintenanceBranch(pulls, prefix = MAINT_PREFIX) {
140	  return openMaintenancePull(pulls, prefix)?.head?.ref ?? null;
141	}
142	
143	// The escalation predicate (owner, 2026-07-23): agent iff a pending agentic note,
144	// or a real change the deterministic converge left non-green. No change, or a
145	// green change with no agentic note, stays agentless.
146	export function shouldRequestAgent({ pendingCount, meaningfulChange, checksPass, selftestOk = true }) {
147	  if (pendingCount > 0) return true;
148	  // A converged mount that cannot pass its own self-test is the judgment case
149	  // whether or not the converge "changed" anything a diff can see: broken
150	  // machinery reports no findings precisely because it is not running.
151	  if (!selftestOk) return true;
152	  return Boolean(meaningfulChange) && !checksPass;
153	}
154	
155	// The scheduler hands the worker a path to signal the agent through; writing it
156	// requests the agent stage (run.mjs files `ready-for-agent` iff it appears).
157	export const AGENT_REQUEST_MARKER = 'agent-requested';
158	
159	// --- CI dispatch on the maintenance PR (#565) --------------------------------
160	// The branch push and the PR open in deliver() both ride the Action's
161	// GITHUB_TOKEN, and GitHub suppresses workflow runs for events that token
162	// authors (its recursion guard) — so the maintenance PR gets NO pull_request
163	// run, auto-merge arms against a green that never arrives, and the PR sits open
164	// forever (#565; the canon-only variant was #432). The guard's one documented
165	// exception is workflow_dispatch: a dispatch POSTed with GITHUB_TOKEN does start
166	// a run, the run's check runs land on the branch-head sha, and that sha is what
167	// the PR's merge gate reads. So deliver() starts the PR's checks itself:
168	// dispatch every workflow that WOULD have run on pull_request and CAN be
169	// dispatched.
170	//
171	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
172	// `on:` block (the worker is dependency-free — no YAML parser). It covers the
173	// shapes workflows actually use: a block map of trigger keys (with or without
174	// nested config), the inline scalar, and the inline list.
175	export function workflowTriggers(yaml) {
176	  const lines = String(yaml ?? '').split('\n');
177	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
178	  if (onAt === -1) return [];
179	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
180	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
181	  const triggers = [];
182	  let childIndent = null;
183	  for (let i = onAt + 1; i < lines.length; i += 1) {
184	    const line = lines[i];
185	    if (!line.trim() || line.trim().startsWith('#')) continue;
186	    const indent = line.length - line.trimStart().length;
187	    if (indent === 0) break;                        // next top-level key — on: is done
188	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
189	    if (indent !== childIndent) continue;           // nested config under a trigger
190	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
191	    if (m) triggers.push(m[1]);
192	  }
193	  return triggers;
194	}
195	
196	// The dispatch plan over the repo's workflow files ({name, content} each):
197	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
198	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
199	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
200	// fix, and silence here would read as "no CI expected" when CI was expected).
201	// A workflow with no pull_request trigger is never touched — dispatchable-but-
202	// unrelated workflows (a release orchestrator, say) must not fire nightly.
203	export function ciDispatchPlan(files) {
204	  const dispatch = [];
205	  const missing = [];
206	  for (const { name, content } of files ?? []) {
207	    const triggers = workflowTriggers(content);
208	    if (!triggers.includes('pull_request')) continue;
209	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
210	  }
211	  return { dispatch, missing };
212	}
213	
214	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
215	
216	const git = (args, opts = {}) =>
217	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
218	const node = (args, extraEnv = {}) =>
219	  execFileSync(process.execPath, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...extraEnv } });
220	
221	async function gh(token, path, { method = 'GET', body } = {}) {
222	  const res = await fetch(`${API}${path}`, {
223	    method,
224	    headers: {
225	      authorization: `Bearer ${token}`,
226	      accept: 'application/vnd.github+json',
227	      'x-github-api-version': '2022-11-28',
228	      ...(body ? { 'content-type': 'application/json' } : {}),
229	    },
230	    body: body ? JSON.stringify(body) : undefined,
231	  });
232	  let json = null;
233	  try { json = await res.json(); } catch { /* empty body */ }
234	  return { status: res.status, json };
235	}
236	
237	// Run check_the_world against the converged repo; true when it exits clean (no
238	// blocking findings). Any non-zero exit / throw means "not green" → judgment left.
239	function checkTheWorldPasses(root) {
240	  const cw = join(root, '.claudinite/shared/engine/checks/check_the_world.mjs');
241	  if (!existsSync(cw)) return true; // no vendored checks to gate on
242	  try { node([cw], { CLAUDE_PROJECT_DIR: root }); return true; }
243	  catch { return false; }
244	}
245	
246	// REHEARSAL MODE (per-project-scheduling rehearsal, #593 phase 0). A run may be
247	// pointed at a canon BRANCH instead of its default head, so a canon change can be
248	// tried against a real repo before it merges. `CLAUDINITE_CANON_REF` selects the
249	// ref; `CLAUDINITE_CANON_URL` a fork.
250	//
251	// The stamp is the whole reason this needs its own decision rather than an extra
252	// clone argument. A branch head is NOT on trunk, and stamping it is precisely the
253	// shape vendoring's #328 anti-rewind guard refuses to write over afterwards
254	// (`ref-not-on-trunk`, which the sheepdog freshness sweep reads as WEDGED, not
255	// late) — a rehearsal would leave the repo unable to baseline ever again. This
256	// was not hypothetical: it happened by hand on 2026-07-30, to all thirteen
257	// members at once, from a converge run out of an unmerged branch.
258	//
259	// So a rehearsal stamps NOTHING. It converges, it reports, and it leaves the
260	// member's provenance exactly as it found it.
261	export function canonSource(env = {}) {
262	  const ref = String(env.CLAUDINITE_CANON_REF ?? '').trim();
263	  const url = String(env.CLAUDINITE_CANON_URL ?? '').trim() || CANON_URL;
264	  return { url, ref: ref || null, rehearsal: Boolean(ref) };
265	}
266	
267	// Why the PR-open POST must be status-checked, as a pure predicate: null when
268	// the PR was created, else the message to fail on.
269	//
270	// This is the one call whose silent failure is invisible AND self-perpetuating.
271	// `openMaintenancePull` reuses by OPEN PR, so a cycle that pushes its branch but
272	// fails to open the PR mints a FRESH branch next cycle, and the next — branches
273	// pile up nightly, the stamp never advances, and the run still reports `ok`
274	// because nothing read the status. The fleet ran exactly that way for two days:
275	// every consumer but the pilot sat on the same canon ref carrying 07-29 and
276	// 07-30 maintenance branches with no PR behind either.
277	//
278	// The usual cause is repo-level and invisible from here — "Allow GitHub Actions
279	// to create and approve pull requests" is off and the POST 403s — so the message
280	// names that remedy rather than leaving a bare status code.
281	export function pullCreateError(status, json) {
282	  if (status === 201 && json?.number) return null;
283	  const detail = json?.message ?? `HTTP ${status}`;
284	  return `${detail} — if this is the Actions PR permission, enable Settings → Actions`
285	    + ' → General → "Allow GitHub Actions to create and approve pull requests"';
286	}
287	
288	// How an `auto-merge` member's PR actually lands, given whether this repo has any
289	// pull_request-triggered workflow at all.
290	//
291	// GitHub's auto-merge is a QUEUE FOR CHECKS. On a repo with no PR CI there is
292	// nothing to queue behind: the mutation is rejected ("Pull request is in clean
293	// status"), and since the failure was swallowed the PR sat open forever — the
294	// stamp never advanced, the next cycle reused the same PR, and a repo that asked
295	// for `auto-merge` got no merge at all. Seven of twelve consumers are in exactly
296	// that shape (no `pull_request` trigger anywhere in .github/workflows).
297	//
298	// So: no CI to wait for → MERGE IT, which is what `auto-merge` meant all along.
299	// CI present → arm, and let the checks gate it as designed.
300	//
301	// `hasPrCi` comes from ciDispatchPlan over the branch's own workflow files —
302	// `dispatch` (startable) plus `missing` (PR-triggered but not dispatchable). Both
303	// empty means no workflow anywhere runs on a pull_request, so no check will ever
304	// appear. That is a fact about the tree, not a race against checks registering.
305	export function deliveryAction({ delivery, hasPrCi }) {
306	  if (delivery !== 'auto-merge') return 'none';
307	  return hasPrCi ? 'arm' : 'merge';
308	}
309	
310	// Run the engine's self-test against the converged tree; true when the machinery
311	// is intact. Same soft shape as checkTheWorldPasses — a missing selftest (an
312	// older mount that predates it) is not a failure, it is nothing to run.
313	function selfTestPasses(root) {
314	  const st = join(root, '.claudinite/shared/engine/selftest.mjs');
315	  if (!existsSync(st)) return true;
316	  try { node([st, '--strict'], { CLAUDE_PROJECT_DIR: root }); return true; }
317	  catch { return false; }
318	}
319	
320	// Deliver the converge as one commit on the per-cycle maintenance branch, native
321	// git. Reuses the family's open PR (by prefix) or mints a dated branch + PR;
322	// arms auto-merge when the member asked for it. Force-push is the regenerate-not-
323	// reconcile stance for this bot-owned branch.
324	async function deliver(root, repo, base, token, delivery, seed) {
325	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
326	  let pr = openMaintenancePull(Array.isArray(pulls) ? pulls : []);
327	  const reuse = Boolean(pr);
328	  let branch = reuse ? pr.head.ref : maintenanceBranchName(new Date().toISOString().slice(0, 10), seed);
329	
330	  git(['-C', root, 'checkout', '-B', branch]);
331	  git(['-C', root, 'add', '-A']);
332	  git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
333	    'commit', '-m', 'Claudinite maintenance: converge vendored mount, wiring, and migration notes']);
334	  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
335	  git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
336	
337	  if (!reuse) {
338	    const body = delivery === 'auto-merge'
339	      ? 'Automated Claudinite maintenance (deterministic converge + any migration notes). Regenerated each cycle; auto-merges once this repo\'s checks pass.'
340	      : 'Automated Claudinite maintenance (deterministic converge + any migration notes). Regenerated each cycle; left for your review.';
341	    const created = await gh(token, `/repos/${repo}/pulls`, {
342	      method: 'POST', body: { head: branch, base, title: 'Claudinite maintenance', body },
343	    });
344	    const failure = pullCreateError(created.status, created.json);
345	    if (failure) throw new Error(`could not open the maintenance PR for ${branch}: ${failure}`);
346	    pr = created.json;
347	  }
348	
349	  // ARM GitHub's native auto-merge (not an immediate merge): the PR lands
350	  // automatically once this repo's required checks pass, and the run never blocks
351	  // on CI. Auto-merge is a GraphQL-only mutation.
352	  //
353	  // RE-ASSERTED EVERY CYCLE, reuse or not. The arm is best-effort, and there are
354	  // three ordinary ways for it to be absent from an open maintenance PR: the
355	  // mutation failed when the PR was opened; the repo had not enabled auto-merge
356	  // yet (a settings change nothing here can see); or the member flipped
357	  // `maintenance.delivery` from `review` to `auto-merge` while this PR was
358	  // already open. Arming only on the opening cycle left all three unrecoverable —
359	  // every later run reuses the branch and never retried, so the PR sat open
360	  // forever. The stable-PR form this superseded re-asserted the arm on every run;
361	  // this restores that. Idempotent: arming an already-armed PR is a no-op.
362	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open above emitted no
363	  // pull_request event, so without this the PR has no runs (#565, the
364	  // ciDispatchPlan block). AFTER the push, so the dispatched runs execute the
365	  // branch's own head; every delivering cycle, since a force-push emits no
366	  // synchronize event either and each new head needs its own runs. Best-effort:
367	  // a dispatch failure must not fail the converge that was already pushed.
368	  //
369	  // It runs BEFORE the delivery decision because it is what establishes whether
370	  // this repo has any PR CI at all — the fact deliveryAction turns on.
371	  const ci = await dispatchCiRuns(token, repo, branch)
372	    .catch((e) => { console.log(`baselining: CI dispatch on ${branch} failed: ${e.message}`); return null; });
373	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
374	
375	  if (pr?.number) {
376	    const action = deliveryAction({ delivery, hasPrCi });
377	    if (action === 'merge') {
378	      const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
379	        method: 'PUT', body: { merge_method: 'squash' },
380	      });
381	      if (res.status === 200) console.log(`baselining: merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`);
382	      else console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
383	    } else if (action === 'arm' && pr.node_id) {
384	      // Surfaced, not swallowed: a failed arm is why a maintenance PR sits open
385	      // forever, and the two usual causes are both fixable repo settings.
386	      await enableAutoMerge(token, pr.node_id)
387	        .catch((e) => console.log(`baselining: could not arm auto-merge on PR #${pr.number}: ${e.message}`
388	          + ' — check Settings → General → "Allow auto-merge"'));
389	    }
390	  }
391	  return branch;
392	}
393	
394	// The I/O half of the CI dispatch (#565): read the workflow files as they exist
395	// ON THE MAINTENANCE BRANCH (the converge may itself have changed them), plan
396	// with ciDispatchPlan, POST a dispatch per selected workflow, and log every
397	// outcome — a silent no-checks PR is exactly the failure mode this exists to
398	// close. Needs the scheduler workflow's `actions: write` (a read-only token
399	// 403s the POST silently — the store-release lesson).
400	async function dispatchCiRuns(token, repo, branch) {
401	  const ref = encodeURIComponent(branch);
